// Tag: Start of Round
// Run at the top of every round (The Field's turn). Rounds 2 and 4 roll and place a hidden hunter.
const MOD = "missing-features";
const combat = game.combat;
const round = combat?.round ?? 0;
if (!combat || round < 1) return ui.notifications.warn("Begin the combat first.");
const scene = combat.scene ?? canvas.scene;
const gm = game.users.filter(u => u.isGM).map(u => u.id);
const say = (content, gmOnly = false) => ChatMessage.create({ content, ...(gmOnly ? { whisper: gm } : {}) });
const table = name => game.tables.getName(name)
  ?? (ui.notifications.error(`Missing table: ${name}. Run Tag: Set Up the Meadow.`), null);

const SUN = {
  1: "The sun is high and warm over the meadow.",
  2: "The sun has slipped a little. The tree's shadow starts to reach.",
  3: "The light turns golden, and the shadows grow long.",
  4: "The sun hangs low and orange, just above the horizon.",
  5: "The sun is touching the edge of the world."
};
const CLOCK = {
  1: "Every ambient creature in the it-player's epoch stops and looks at them. Tell only those who can see it.",
  2: "The wisps circle whoever is it. Hunter #1 arrives at the edge.",
  3: "Hunter #1's last round. The wisps feed: 1d4 necrotic at the start of the it-player's turn.",
  4: "Hunter #2 arrives. Ruka changes the rules this round: New rule! or Double tag!",
  5: "Hunter #2's last round. The Grandfather: \"Nearly suppertime!\" If Ruka isn't tagged by the end of this round, the game is lost."
};

await say(`<h3>Round ${round}</h3><p>${SUN[round] ?? "The sun has set."}</p>`);
if (round > 5) return say("<p><strong>Sunset.</strong> If Ruka wasn't tagged, the game is lost: 2d8 to everyone, back to the swamp's edge, and everyone rerolls their home epoch.</p>", true);
await say(`<p><strong>Clock:</strong> ${CLOCK[round]}</p>`, true);
await table("Tag - Field (d6)")?.draw();

// Hunter #1 sinks back at the start of round 4
const hunters = scene.tokens.filter(t => t.getFlag(MOD, "hunter"));
if (round === 4 && hunters.length) {
  const ids = hunters.map(t => t.id);
  const cids = combat.combatants.filter(c => ids.includes(c.tokenId)).map(c => c.id);
  if (cids.length) await combat.deleteEmbeddedDocuments("Combatant", cids);
  await scene.deleteEmbeddedDocuments("Token", ids);
  await say("<p>Hunter #1 sinks back into its epoch.</p>", true);
}
if (![2, 4].includes(round)) return;

// Whose epoch? The hunter always comes from whoever is it.
const EPOCHS = ["Sea", "Ice", "Stone", "First Forest", "Hills", "Meadow"];
const options = EPOCHS.map((e, i) => `<option value="${i}" ${e === "Meadow" ? "selected" : ""}>${i + 1}. ${e}</option>`).join("");
const epoch = await foundry.applications.api.DialogV2.prompt({
  window: { title: `Hunter #${round / 2}: whoever is it` },
  content: `<p>Home epoch of whoever is it. (Today: Earl is Meadow; Norm and Gideon are Hills.)</p><select name="epoch">${options}</select>`,
  ok: { label: "Roll the hunter", callback: (event, button) => Number(button.form.elements.epoch.value) }
}).catch(() => null);
if (epoch === null || epoch === undefined) return;

const ht = table(`Hunter ${epoch + 1} - ${EPOCHS[epoch]} (d4)`);
if (!ht) return;
const { results } = await ht.draw({ rollMode: CONST.DICE_ROLL_MODES.PRIVATE });
const text = (results[0].description || results[0].text || results[0].name || "").replace(/<[^>]*>/g, "").trim();
const name = text.split(" (")[0];
const count = text.includes("pair") ? 2 : 1;

// Import it and place it, hidden, at the field's edge
const pack = game.packs.get(`${MOD}.monsters`);
const entry = (await pack.getIndex()).find(e => e.name === name);
if (!entry) return ui.notifications.error(`No monster named "${name}" in the Monsters compendium.`);
const folder = game.folders.find(f => f.type === "Actor" && f.name === "Tag") ?? await Folder.create({ name: "Tag", type: "Actor" });
const actor = game.actors.getName(name) ?? await game.actors.importFromCompendium(pack, entry._id, { folder: folder.id });

const C = 1400, PX = 20, size = canvas.grid.size;
const angle = Math.random() * 2 * Math.PI;
const w = actor.prototypeToken.width * size;
const docs = [];
for (let i = 0; i < count; i++) {
  const a = angle + i * 0.15;
  const td = await actor.getTokenDocument({
    x: C + Math.cos(a) * 54 * PX - w / 2, y: C + Math.sin(a) * 54 * PX - w / 2,
    hidden: true, flags: { [MOD]: { hunter: true } }
  });
  docs.push(td.toObject());
}
const tokens = await scene.createEmbeddedDocuments("Token", docs);
await combat.createEmbeddedDocuments("Combatant",
  tokens.map(t => ({ tokenId: t.id, sceneId: scene.id, actorId: t.actorId, hidden: true })));

// It acts right after Ruka
const ruka = combat.combatants.find(c => c.name === "Ruka");
for (const t of tokens) {
  const c = combat.combatants.find(x => x.tokenId === t.id);
  if (c && ruka?.initiative != null) await combat.setInitiative(c.id, ruka.initiative - 0.1);
}
await say(`<p><strong>Hunter #${round / 2}:</strong> ${count === 2 ? "two of " : ""}${name}, from the ${EPOCHS[epoch]}, hidden at the field's edge. ` +
  `Reveal the token when the field rolls ${epoch + 1}, or when someone reveals it.</p>`, true);
